     1→// packages/core/src/account/ops/test.ts
     2→
     3→import { findAccount } from "./crud";
     4→import { getExchange } from "./exchanges";
     5→import type { Credentials } from "./exchanges";
     6→import type { TestResult } from "./types";
     7→
     8→export async function testAccount(idOrName: string): Promise<TestResult> {
     9→  const record = await findAccount(idOrName);
    10→  if (!record) return { success: false, error: `Account not found: ${idOrName}` };
    11→
    12→  const exchange = getExchange(record.exchange);
    13→  const credentials: Credentials = {
    14→    api_key: record.api_key,
    15→    secret: record.secret,
    16→    passphrase: record.passphrase,
    17→  };
    18→
    19→  return exchange.testConnection(credentials);
    20→}
    21→

