     1→// packages/core/src/account/ops/crud.test.ts
     2→
     3→import { describe, it, expect, beforeEach, afterEach, vi } from "vitest";
     4→import { join } from "node:path";
     5→import { mkdirSync, rmSync } from "node:fs";
     6→
     7→const TEST_DIR = join(__dirname, "__test_tmp_crud__");
     8→vi.mock("../../config/paths", () => ({
     9→  getAccountsPath: () => join(TEST_DIR, "accounts.yaml"),
    10→  getStateDir: () => TEST_DIR,
    11→}));
    12→
    13→import {
    14→  listAccounts,
    15→  addAccount,
    16→  viewAccount,
    17→  updateAccount,
    18→  removeAccount,
    19→  findAccount,
    20→} from "./crud";
    21→
    22→describe("crud", () => {
    23→  beforeEach(() => {
    24→    mkdirSync(TEST_DIR, { recursive: true });
    25→  });
    26→
    27→  afterEach(() => {
    28→    rmSync(TEST_DIR, { recursive: true, force: true });
    29→  });
    30→
    31→  describe("addAccount", () => {
    32→    it("creates account with valid input", async () => {
    33→      const result = await addAccount({
    34→        exchange: "okx",
    35→        name: "OKX Test",
    36→        api_key: "test-api-key-12345678",
    37→        secret: "test-secret-12345678",
    38→        passphrase: "test-passphrase",
    39→      });
    40→      expect(result.success).toBe(true);
    41→      expect(result.account).toBeDefined();
    42→      expect(result.account!.name).toBe("OKX Test");
    43→      expect(result.account!.exchange).toBe("okx");
    44→      expect(result.account!.id).toHaveLength(12);
    45→    });
    46→
    47→    it("rejects empty api_key", async () => {
    48→      const result = await addAccount({
    49→        exchange: "okx",
    50→        name: "Test",
    51→        api_key: "  ",
    52→        secret: "secret",
    53→        passphrase: "pass",
    54→      });
    55→      expect(result.success).toBe(false);
    56→      expect(result.error).toContain("api_key");
    57→    });
    58→
    59→    it("rejects missing passphrase for OKX", async () => {
    60→      const result = await addAccount({
    61→        exchange: "okx",
    62→        name: "Test",
    63→        api_key: "key",
    64→        secret: "secret",
    65→      });
    66→      expect(result.success).toBe(false);
    67→      expect(result.error).toContain("passphrase");
    68→    });
    69→
    70→    it("allows missing passphrase for Binance", async () => {
    71→      const result = await addAccount({
    72→        exchange: "binance",
    73→        name: "Binance Test",
    74→        api_key: "key",
    75→        secret: "secret",
    76→      });
    77→      expect(result.success).toBe(true);
    78→    });
    79→
    80→    it("rejects name exceeding 64 chars", async () => {
    81→      const result = await addAccount({
    82→        exchange: "binance",
    83→        name: "A".repeat(65),
    84→        api_key: "key",
    85→        secret: "secret",
    86→      });
    87→      expect(result.success).toBe(false);
    88→      expect(result.error).toContain("max length");
    89→    });
    90→
    91→    it("trims whitespace from credentials", async () => {
    92→      const result = await addAccount({
    93→        exchange: "binance",
    94→        name: "  Binance  ",
    95→        api_key: "  key  ",
    96→        secret: "  secret  ",
    97→      });
    98→      expect(result.success).toBe(true);
    99→      expect(result.account!.name).toBe("Binance");
   100→    });
   101→  });
   102→
   103→  describe("listAccounts", () => {
   104→    it("returns empty list initially", async () => {
   105→      const result = await listAccounts();
   106→      expect(result.success).toBe(true);
   107→      expect(result.accounts).toEqual([]);
   108→    });
   109→
   110→    it("returns accounts without credentials", async () => {
   111→      await addAccount({ exchange: "binance", name: "B1", api_key: "k", secret: "s" });
   112→      const result = await listAccounts();
   113→      expect(result.accounts).toHaveLength(1);
   114→      // Account should not contain credentials
   115→      const acc = result.accounts[0] as unknown as Record<string, unknown>;
   116→      expect(acc.api_key).toBeUndefined();
   117→      expect(acc.secret).toBeUndefined();
   118→    });
   119→  });
   120→
   121→  describe("viewAccount", () => {
   122→    it("finds by ID", async () => {
   123→      const created = await addAccount({
   124→        exchange: "binance",
   125→        name: "B1",
   126→        api_key: "mykey123",
   127→        secret: "mysecret",
   128→      });
   129→      const result = await viewAccount(created.account!.id);
   130→      expect(result.success).toBe(true);
   131→      expect(result.masked_credentials!.api_key).toBe("****y123");
   132→      expect(result.masked_credentials!.secret).toBe("****cret");
   133→    });
   134→
   135→    it("finds by name", async () => {
   136→      await addAccount({ exchange: "binance", name: "UniqueB", api_key: "key", secret: "secret" });
   137→      const result = await viewAccount("UniqueB");
   138→      expect(result.success).toBe(true);
   139→      expect(result.account!.name).toBe("UniqueB");
   140→    });
   141→
   142→    it("errors on ambiguous name", async () => {
   143→      await addAccount({ exchange: "binance", name: "Dup", api_key: "k1", secret: "s1" });
   144→      await addAccount({ exchange: "okx", name: "Dup", api_key: "k2", secret: "s2", passphrase: "p" });
   145→      const result = await viewAccount("Dup");
   146→      expect(result.success).toBe(false);
   147→      expect(result.error).toContain("Multiple accounts");
   148→    });
   149→
   150→    it("errors on not found", async () => {
   151→      const result = await viewAccount("nonexistent");
   152→      expect(result.success).toBe(false);
   153→      expect(result.error).toContain("not found");
   154→    });
   155→  });
   156→
   157→  describe("updateAccount", () => {
   158→    it("updates name", async () => {
   159→      const created = await addAccount({ exchange: "binance", name: "Old", api_key: "k", secret: "s" });
   160→      const result = await updateAccount(created.account!.id, { name: "New" });
   161→      expect(result.success).toBe(true);
   162→      expect(result.account!.name).toBe("New");
   163→    });
   164→
   165→    it("updates credentials", async () => {
   166→      const created = await addAccount({
   167→        exchange: "binance",
   168→        name: "B",
   169→        api_key: "old-key",
   170→        secret: "old-secret",
   171→      });
   172→      await updateAccount(created.account!.id, { api_key: "new-key" });
   173→      const view = await viewAccount(created.account!.id);
   174→      expect(view.masked_credentials!.api_key).toBe("****-key");
   175→    });
   176→
   177→    it("refreshes updated_at", async () => {
   178→      const created = await addAccount({ exchange: "binance", name: "B", api_key: "k", secret: "s" });
   179→      // Small delay to ensure different timestamp
   180→      await new Promise((r) => setTimeout(r, 10));
   181→      const result = await updateAccount(created.account!.id, { name: "B2" });
   182→      expect(result.account!.updated_at).not.toBe(created.account!.created_at);
   183→    });
   184→
   185→    it("errors on ambiguous name", async () => {
   186→      await addAccount({ exchange: "binance", name: "Same", api_key: "k1", secret: "s1" });
   187→      await addAccount({ exchange: "gate", name: "Same", api_key: "k2", secret: "s2" });
   188→      const result = await updateAccount("Same", { name: "New" });
   189→      expect(result.success).toBe(false);
   190→      expect(result.error).toContain("Multiple accounts");
   191→    });
   192→  });
   193→
   194→  describe("removeAccount", () => {
   195→    it("removes by ID", async () => {
   196→      const created = await addAccount({ exchange: "binance", name: "B1", api_key: "k", secret: "s" });
   197→      const result = await removeAccount(created.account!.id);
   198→      expect(result.success).toBe(true);
   199→      const list = await listAccounts();
   200→      expect(list.accounts).toHaveLength(0);
   201→    });
   202→
   203→    it("removes by name", async () => {
   204→      await addAccount({ exchange: "binance", name: "ToRemove", api_key: "k", secret: "s" });
   205→      const result = await removeAccount("ToRemove");
   206→      expect(result.success).toBe(true);
   207→    });
   208→
   209→    it("errors on not found", async () => {
   210→      const result = await removeAccount("nope");
   211→      expect(result.success).toBe(false);
   212→    });
   213→
   214→    it("errors on ambiguous name", async () => {
   215→      await addAccount({ exchange: "binance", name: "Dup", api_key: "k1", secret: "s1" });
   216→      await addAccount({ exchange: "gate", name: "Dup", api_key: "k2", secret: "s2" });
   217→      const result = await removeAccount("Dup");
   218→      expect(result.success).toBe(false);
   219→      expect(result.error).toContain("Multiple accounts");
   220→    });
   221→  });
   222→
   223→  describe("findAccount", () => {
   224→    it("returns null for no match", async () => {
   225→      const result = await findAccount("nothing");
   226→      expect(result).toBeNull();
   227→    });
   228→
   229→    it("prefers ID over name", async () => {
   230→      const created = await addAccount({ exchange: "binance", name: "SomeName", api_key: "k", secret: "s" });
   231→      const result = await findAccount(created.account!.id);
   232→      expect(result).not.toBeNull();
   233→      expect(result!.id).toBe(created.account!.id);
   234→    });
   235→  });
   236→});
   237→

