    95→/**
    96→ * Mock Fastify instance for testing route handlers
    97→ */
    98→interface MockReply {
    99→  code: ReturnType<typeof vi.fn>;
   100→}
   101→
   102→interface RouteOptions {
   103→  schema?: unknown;
   104→}
   105→
   106→interface MockRouteHandler {
   107→  method: string;
   108→  url: string;
   109→  handler: (request: unknown, reply: MockReply) => Promise<unknown>;
   110→}
   111→
   112→function createMockFastify() {
   113→  const routes: MockRouteHandler[] = [];
   114→
   115→  const fastify = {
   116→    get: vi.fn((url: string, optionsOrHandler: RouteOptions | ((req: unknown, rep: MockReply) => Promise<unknown>), handler?: (req: unknown, rep: MockReply) => Promise<unknown>) => {
   117→      const actualHandler = typeof optionsOrHandler === "function" ? optionsOrHandler : handler!;
   118→      routes.push({ method: "GET", url, handler: actualHandler });
   119→    }),
   120→    post: vi.fn((url: string, optionsOrHandler: RouteOptions | ((req: unknown, rep: MockReply) => Promise<unknown>), handler?: (req: unknown, rep: MockReply) => Promise<unknown>) => {
   121→      const actualHandler = typeof optionsOrHandler === "function" ? optionsOrHandler : handler!;
   122→      routes.push({ method: "POST", url, handler: actualHandler });
   123→    }),
   124→    put: vi.fn((url: string, optionsOrHandler: RouteOptions | ((req: unknown, rep: MockReply) => Promise<unknown>), handler?: (req: unknown, rep: MockReply) => Promise<unknown>) => {
   125→      const actualHandler = typeof optionsOrHandler === "function" ? optionsOrHandler : handler!;
   126→      routes.push({ method: "PUT", url, handler: actualHandler });
   127→    }),
   128→    patch: vi.fn((url: string, optionsOrHandler: RouteOptions | ((req: unknown, rep: MockReply) => Promise<unknown>), handler?: (req: unknown, rep: MockReply) => Promise<unknown>) => {
   129→      const actualHandler = typeof optionsOrHandler === "function" ? optionsOrHandler : handler!;
   130→      routes.push({ method: "PATCH", url, handler: actualHandler });
   131→    }),
   132→    delete: vi.fn((url: string, handler: (req: unknown, rep: MockReply) => Promise<unknown>) => {
   133→      routes.push({ method: "DELETE", url, handler });
   134→    }),
   135→    routes,
   136→    // Helper to find and execute a route handler
   137→    async inject(options: { method: string; url: string; payload?: unknown }) {
   138→      const { method, url, payload } = options;
   139→      const parsedUrl = new URL(url, "http://localhost");
   140→      const pathname = parsedUrl.pathname;
   141→      const searchParams = Object.fromEntries(parsedUrl.searchParams.entries());
   142→
   143→      // Convert string params to appropriate types
   144→      const query: Record<string, unknown> = {};
   145→      for (const [key, value] of Object.entries(searchParams)) {
   146→        query[key] = value;
   147→      }
   148→
   149→      // Find matching route
   150→      let matchingRoute: MockRouteHandler | undefined;
   151→      let params: Record<string, string> = {};
   152→
   153→      for (const route of routes) {
   154→        if (route.method !== method) continue;
   155→
   156→        // Check for exact match
   157→        if (route.url === pathname) {
   158→          matchingRoute = route;
   159→          break;
   160→        }
   161→
   162→        // Check for parameterized match (e.g., /api/models/:id)
   163→        const routeParts = route.url.split("/");
   164→        const urlParts = pathname.split("/");
   165→
   166→        if (routeParts.length === urlParts.length) {
   167→          let isMatch = true;
   168→          const extractedParams: Record<string, string> = {};
   169→
   170→          for (let i = 0; i < routeParts.length; i++) {
   171→            if (routeParts[i].startsWith(":")) {
   172→              extractedParams[routeParts[i].slice(1)] = urlParts[i];
   173→            } else if (routeParts[i] !== urlParts[i]) {
   174→              isMatch = false;
   175→              break;
   176→            }
   177→          }
   178→
   179→          if (isMatch) {
   180→            matchingRoute = route;
   181→            params = extractedParams;
   182→            break;
   183→          }
   184→        }
   185→      }
   186→
   187→      if (!matchingRoute) {
   188→        return {
   189→          statusCode: 404,
   190→          body: JSON.stringify({ error: "Route not found" }),
   191→        };
   192→      }
   193→
   194→      // Create mock request and reply
   195→      const request = {
   196→        query,
   197→        params,
   198→        body: payload,
   199→      };
   200→
   201→      let statusCode = 200;
   202→      const reply: MockReply = {
   203→        code: vi.fn((code: number) => {
   204→          statusCode = code;
   205→          return reply;
   206→        }),
   207→      };
   208→
   209→      const result = await matchingRoute.handler(request, reply);
   210→
   211→      return {
   212→        statusCode,
   213→        body: JSON.stringify(result),
   214→      };
   215→    },
   216→  };
   217→
   218→  return fastify;
   219→}
